def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "guide_to_garden": And([
            self.activity_chosen(self.exercise),
            Not(self.activity_chosen(self.volunteering)),
            self.adoption_event_active,
            self.alexander_open_to_suggestions
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
